top_5_drugs = Drugs.CALCULATE(
    drug_name=drug_name,
    num_treatments=COUNT(treatments_used_in),
    avg_drug_amount=AVG(treatments_used_in.tot_drug_amt)
).WHERE(
    HAS(treatments_used_in) == 1
).TOP_K(
    5,
    by=num_treatments.DESC()
).ORDER_BY(
    num_treatments.DESC(),
    drug_name.ASC()
)

