            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).WHERE(
    HAS(sessions.WHERE(
        (session_start_ts >= "2023-06-01") & 
        (session_start_ts < "2023-06-08")
    )) == 1
).ORDER_BY(total_duration.DESC())

user_session_duration = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
        ).CALCULATE(
            duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_in_seconds
    )
).ORDER_BY(total_duration.DESC())

